-- Adds planner features and validation without replacing saved family plans.

begin;

alter table public.planner_push_subscriptions add column if not exists snoozed_until timestamptz;

create or replace function public.planner_reward_balance(document jsonb, person text)
returns bigint language sql immutable set search_path = '' as $$
  select (select count(*) from jsonb_array_elements(document->'tasks') t where t->>'memberId'=person and (t->>'done')::boolean and t ? 'doneAt')
    + (select count(*) from jsonb_array_elements(coalesce(document->'routineChecks','[]')) c
      join jsonb_array_elements(coalesce(document->'routines','[]')) r on r->>'id'=c->>'routineId'
      where c->>'memberId'=person and jsonb_array_length(c->'steps')=jsonb_array_length(r->'steps')
        and (r->'days') @> to_jsonb(extract(dow from (c->>'date')::date)::int)
        and (not (r ? 'from') or c->>'date'>=r->>'from') and (not (r ? 'until') or c->>'date'<=r->>'until')
        and not coalesce((r->'excludedDates') ? (c->>'date'),false)
        and not exists(select 1 from jsonb_array_elements(coalesce(r->'excludedRanges','[]')) x where c->>'date' between x->>'start' and x->>'end'))
    - coalesce((select sum((c->>'cost')::bigint) from jsonb_array_elements(coalesce(document->'rewardClaims','[]')) c where c->>'memberId'=person),0);
$$;

create or replace function public.planner_validate_features(document jsonb)
returns boolean language plpgsql immutable set search_path = '' as $$
declare collection text; item jsonb; reference text; parent jsonb; entry jsonb; key text; member_ids text[]; catalogue_ids text[] := array['pasta','tacos','salmon','curry','pizza','pancakes','nigerian-jollof','ghanaian-jollof','red-red','waakye','kelewele','groundnut-soup','tatale','egusi-soup','efo-riro','akara','moi-moi','ewa-riro','chicken-suya','asaro','chicken-yassa','thieboudienne','ndambe','beef-maafe','domoda','vegetable-benachin','kedjenou','attieke-fish','fonio-pilaf','plasas','kontomire-spinach','garden-egg-stew','ghana-fish-light-soup','ghana-tuna-cabbage','ghana-chicken-carrots','yam-eto','ghana-corn-porridge','ghana-egg-stew','lentil-bolognese','chicken-traybake','vegetable-couscous','overnight-oats','shakshuka','egg-fried-rice','chicken-stir-fry','crispy-tofu-bowls','minestrone','tomato-bean-soup','three-bean-chilli','beef-chilli','salmon-fishcakes','tuna-pasta-bake','chicken-noodle-soup','mushroom-risotto','spinach-frittata','stuffed-sweet-potatoes','chickpea-wraps','turkey-meatballs','shepherds-pie','vegetable-noodles','teriyaki-salmon','peanut-noodles','breakfast-burritos','apple-porridge','yoghurt-granola-bowls','vegetable-lasagne','chicken-fajitas','lemon-pea-orzo'];
begin
  select array_agg(m->>'id') into member_ids from jsonb_array_elements(document->'members') m;
  foreach collection in array array['recipePrefs','routines','routineChecks','rewards','rewardClaims','comments','expenses'] loop
    for item in select * from jsonb_array_elements(coalesce(document->collection,'[]')) loop
      if not ((item->>'memberId')=any(member_ids)) then return false; end if;
    end loop;
  end loop;
  if exists(select 1 from jsonb_array_elements(coalesce(document->'recipePrefs','[]')) p group by p->>'memberId',p->>'recipeId' having count(*)>1) then return false; end if;
  if exists(select 1 from jsonb_array_elements(coalesce(document->'customRecipes','[]')) r where r->>'id'=any(catalogue_ids)) then return false; end if;
  select catalogue_ids||coalesce(array_agg(r->>'id'),array[]::text[]) into catalogue_ids from jsonb_array_elements(coalesce(document->'customRecipes','[]')) r;
  for item in select * from jsonb_array_elements(coalesce(document->'recipePrefs','[]')) loop
    if not ((item->>'recipeId')=any(catalogue_ids)) then return false; end if;
  end loop;
  for parent in select * from jsonb_array_elements(coalesce(document->'mealTemplates','[]')) loop
    if exists(select 1 from jsonb_array_elements(parent->'entries') e group by e->>'weekday',e->>'slot' having count(*)>1) then return false; end if;
    for item in select * from jsonb_array_elements(parent->'entries') loop
      if (item ? 'recipeId')=(item ? 'note') or (item ? 'recipeId' and not ((item->>'recipeId')=any(catalogue_ids))) then return false; end if;
    end loop;
  end loop;
  if (document->'settings' ? 'quietStart')<>(document->'settings' ? 'quietEnd') then return false; end if;

  for item in select * from jsonb_array_elements(document->'meals') loop
    if (item ? 'recipeId') = (item ? 'note') then return false; end if;
  end loop;
  for item in select * from jsonb_array_elements(document->'events') loop
    foreach key in array array['dropOffMemberId','pickupMemberId'] loop
      if item ? key and not ((item->>key)=any(member_ids)) then return false; end if;
    end loop;
    if (select count(*)<>count(distinct x->>'id') from jsonb_array_elements(coalesce(item->'checklist','[]')) x) then return false; end if;
    for key,entry in select * from jsonb_each(coalesce(item->'checklistDone','{}')) loop
      if to_char(key::date,'YYYY-MM-DD')<>key then return false; end if;
      for reference in select jsonb_array_elements_text(entry) loop
        if not exists(select 1 from jsonb_array_elements(coalesce(item->'checklist','[]')) c where c->>'id'=reference) then return false; end if;
      end loop;
    end loop;
  end loop;
  for item in select * from jsonb_array_elements(coalesce(document->'routines','[]')) loop
    if item ? 'until' and item ? 'from' and item->>'until'<item->>'from' then return false; end if;
    if (select count(*)<>count(distinct x->>'id') from jsonb_array_elements(item->'steps') x) then return false; end if;
  end loop;
  foreach collection in array array['events','routines'] loop
    for item in select * from jsonb_array_elements(coalesce(document->collection,'[]')) loop
      for entry in select * from jsonb_array_elements(coalesce(item->'excludedRanges','[]')) loop
        if (entry->>'end')::date<(entry->>'start')::date or (entry->>'end')::date-(entry->>'start')::date>366 then return false; end if;
      end loop;
      for reference in select jsonb_array_elements_text(coalesce(item->'excludedDates','[]')) loop
        if to_char(reference::date,'YYYY-MM-DD')<>reference then return false; end if;
      end loop;
    end loop;
  end loop;
  for item in select * from jsonb_array_elements(coalesce(document->'routineChecks','[]')) loop
    select r into parent from jsonb_array_elements(coalesce(document->'routines','[]')) r where r->>'id'=item->>'routineId';
    if parent is null or item->>'memberId'<>parent->>'memberId' or item->>'id'<>(parent->>'id')||':'||(item->>'date') then return false; end if;
    if to_char((item->>'date')::date,'YYYY-MM-DD')<>item->>'date' then return false; end if;
    if (select count(*)<>count(distinct x) from jsonb_array_elements_text(item->'steps') x) then return false; end if;
    for reference in select jsonb_array_elements_text(item->'steps') loop
      if not exists(select 1 from jsonb_array_elements(parent->'steps') x where x->>'id'=reference) then return false; end if;
    end loop;
  end loop;
  for item in select * from jsonb_array_elements(coalesce(document->'rewardClaims','[]')) loop
    select r into parent from jsonb_array_elements(coalesce(document->'rewards','[]')) r where r->>'id'=item->>'rewardId';
    if parent is null or item->>'memberId'<>parent->>'memberId' or item->>'cost'<>parent->>'cost' or item->>'id'<>(parent->>'id')||':'||(item->>'date') then return false; end if;
  end loop;
  foreach collection in array array['comments','eventLinks'] loop
    for item in select * from jsonb_array_elements(coalesce(document->collection,'[]')) loop
      if not exists(select 1 from jsonb_array_elements(document->'events') e where e->>'id'=item->>'eventId') then return false; end if;
    end loop;
  end loop;
  foreach collection in array array['pantry','expenses','rewardClaims'] loop
    for item in select * from jsonb_array_elements(coalesce(document->collection,'[]')) loop
      foreach key in array array['date','useBy'] loop
        if item ? key and to_char((item->>key)::date,'YYYY-MM-DD')<>item->>key then return false; end if;
      end loop;
    end loop;
  end loop;
  if document->'settings' ? 'timezone' and not exists(select 1 from pg_timezone_names where name=document->'settings'->>'timezone') then return false; end if;
  return true;
exception when others then return false;
end;
$$;

