  if exists(select 1 from jsonb_array_elements(document->'meals') m group by m->>'date', m->>'slot' having count(*) > 1) then return false; end if;
  foreach collection in array array['members','events','tasks','shopping','meals','notes','recipePrefs','customRecipes','mealTemplates','pantry','routines','routineChecks','rewards','rewardClaims','comments','eventLinks','expenses','activity'] loop
    if (select count(*) <> count(distinct e->>'id') from jsonb_array_elements(document->collection) e) then return false; end if;
    for item in select * from jsonb_array_elements(document->collection) loop
      if collection in ('tasks','notes') and not ((item->>'memberId') = any(member_ids)) then return false; end if;
      -- Everyone taking turns at a chore must be in the family (mirrors taskSchema).
      if collection = 'tasks' and item ? 'rotation' then
        for reference in select jsonb_array_elements_text(item->'rotation') loop
          if not (reference = any(member_ids)) then return false; end if;
        end loop;
      end if;
      if collection = 'events' then
        -- Mirrors eventSchema in src/lib/data.ts. Multi-day and all-day events may end at an earlier clock time.
        if coalesce(item->>'endDate', item->>'date') = item->>'date'
          and not coalesce((item->>'allDay')::boolean, false)
          and item->>'end' <= item->>'start' then return false; end if;
        if item ? 'endDate' and (to_char((item->>'endDate')::date,'YYYY-MM-DD') <> item->>'endDate'
          or item->>'endDate' < item->>'date') then return false; end if;
        if item ? 'until' and (to_char((item->>'until')::date,'YYYY-MM-DD') <> item->>'until'
          or item->>'until' < item->>'date') then return false; end if;
        -- A repeating event must end before it repeats.
        if item ? 'endDate' and item->>'repeat' <> 'none'
          and (item->>'endDate')::date - (item->>'date')::date >= (case item->>'repeat'
            when 'weekly' then 7 when 'fortnightly' then 14 when 'monthly' then 28 else 365 end)
          then return false; end if;
        for reference in select jsonb_array_elements_text(item->'memberIds') loop
          if not (reference = any(member_ids)) then return false; end if;
        end loop;
      end if;
      if collection in ('events','meals') and to_char((item->>'date')::date,'YYYY-MM-DD') <> item->>'date' then return false; end if;
      if collection = 'tasks' and to_char((item->>'due')::date,'YYYY-MM-DD') <> item->>'due' then return false; end if;
      if collection = 'meals' and item ? 'recipeId' and item->>'recipeId' not in ('pasta','tacos','salmon','curry','pizza','pancakes','nigerian-jollof','ghanaian-jollof','red-red','waakye','kelewele','groundnut-soup','tatale','egusi-soup','efo-riro','akara','moi-moi','ewa-riro','chicken-suya','asaro','chicken-yassa','thieboudienne','ndambe','beef-maafe','domoda','vegetable-benachin','kedjenou','attieke-fish','fonio-pilaf','plasas','kontomire-spinach','garden-egg-stew','ghana-fish-light-soup','ghana-tuna-cabbage','ghana-chicken-carrots','yam-eto','ghana-corn-porridge','ghana-egg-stew','lentil-bolognese','chicken-traybake','vegetable-couscous','overnight-oats','shakshuka','egg-fried-rice','chicken-stir-fry','crispy-tofu-bowls','minestrone','tomato-bean-soup','three-bean-chilli','beef-chilli','salmon-fishcakes','tuna-pasta-bake','chicken-noodle-soup','mushroom-risotto','spinach-frittata','stuffed-sweet-potatoes','chickpea-wraps','turkey-meatballs','shepherds-pie','vegetable-noodles','teriyaki-salmon','peanut-noodles','breakfast-burritos','apple-porridge','yoghurt-granola-bowls','vegetable-lasagne','chicken-fajitas','lemon-pea-orzo') and not exists(select 1 from jsonb_array_elements(coalesce(document->'customRecipes','[]')) r where r->>'id'=item->>'recipeId') then return false; end if;
    end loop;
  end loop;
  return public.planner_validate_features(document);
exception when others then return false;
end;
$$;

create or replace function public.planner_apply_changes(family_id uuid, changes jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare document jsonb; change jsonb; collection text; action text; items jsonb; record_id text;
  previous jsonb; value jsonb; actor_member text; actor_name text; owner uuid; history jsonb := '[]'; before_text text; after_text text; involved jsonb;
begin
  if auth.uid() is null then raise exception 'Sign in first.'; end if;
  if jsonb_typeof(changes) is distinct from 'array' or octet_length(changes::text) > 5000000 then raise exception 'Invalid changes.'; end if;
  if jsonb_array_length(changes) > 1000 then raise exception 'Please save fewer changes at once.'; end if;
  -- Lock the latest document before applying changes. Concurrent clients cannot overwrite unrelated changes.
  select h.data into document from public.planner_households h where h.id = family_id for update;
  if not public.planner_is_member(family_id) then raise exception 'This family space is private.'; end if;
  select m.member_id into actor_member from public.planner_memberships m where m.household_id=family_id and m.user_id=auth.uid();
  select h.owner_id into owner from public.planner_households h where h.id=family_id;
  select p->>'name' into actor_name from jsonb_array_elements(document->'members') p where p->>'id'=actor_member;
  for change in select * from jsonb_array_elements(changes) loop
    collection := change->>'collection'; action := change->>'action';
    if collection is null or action is null then raise exception 'Invalid change.'; end if;
    if collection = 'settings' and action = 'settings' then
      document := jsonb_set(document,'{settings}',change->'value');
    elsif collection in ('members','events','tasks','shopping','meals','notes','recipePrefs','customRecipes','mealTemplates','pantry','routines','routineChecks','rewards','rewardClaims','comments','eventLinks','expenses') and action in ('upsert','remove') then
      if action = 'upsert' then record_id := change->'value'->>'id'; else record_id := change->>'id'; end if;
      if record_id is null or length(record_id) < 1 then raise exception 'An item ID is required.'; end if;
      select e into previous from jsonb_array_elements(coalesce(document->collection,'[]')) e where e->>'id'=record_id;
      value := case when action='upsert' then change->'value' else null end;
      if collection='recipePrefs' and action='upsert' and value->>'memberId' is distinct from actor_member then raise exception 'Choose your own recipe favourites.'; end if;
      if collection='rewardClaims' and (action='remove' or coalesce((value->>'approved')::boolean,false)) and owner is distinct from auth.uid() then raise exception 'Only the family owner approves or declines rewards.'; end if;
      if collection='comments' then
        if previous is not null and previous->>'memberId' is distinct from actor_member and owner is distinct from auth.uid() then raise exception 'Only the author or family owner can change a comment.'; end if;
        if action='upsert' then
          value := jsonb_set(jsonb_set(value,'{memberId}',to_jsonb(actor_member)),'{createdAt}',coalesce(previous->'createdAt',to_jsonb(to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))));
          change := jsonb_set(change,'{value}',value);
        end if;
      end if;
      if collection in ('events','tasks','comments') and previous is distinct from value and actor_member is not null then
        before_text := case when previous is null then '' when collection='comments' then previous->>'body' else concat_ws(' · ',previous->>'title',previous->>'date',previous->>'start',previous->>'end',previous->>'location',case when previous ? 'dropOffMemberId' then 'Drop-off: '||coalesce((select m.person->>'name' from jsonb_array_elements(document->'members') as m(person) where m.person->>'id'=previous->>'dropOffMemberId'),'Unassigned') end,case when previous ? 'pickupMemberId' then 'Pickup: '||coalesce((select m.person->>'name' from jsonb_array_elements(document->'members') as m(person) where m.person->>'id'=previous->>'pickupMemberId'),'Unassigned') end,case when previous ? 'excludedDates' then 'Skipped dates: '||(previous->'excludedDates')::text end,case when previous ? 'excludedRanges' then 'Holiday dates: '||(previous->'excludedRanges')::text end,case when previous ? 'done' then case when (previous->>'done')::boolean then 'Done' else 'To do' end end) end;
        after_text := case when value is null then '' when collection='comments' then value->>'body' else concat_ws(' · ',value->>'title',value->>'date',value->>'start',value->>'end',value->>'location',case when value ? 'dropOffMemberId' then 'Drop-off: '||coalesce((select m.person->>'name' from jsonb_array_elements(document->'members') as m(person) where m.person->>'id'=value->>'dropOffMemberId'),'Unassigned') end,case when value ? 'pickupMemberId' then 'Pickup: '||coalesce((select m.person->>'name' from jsonb_array_elements(document->'members') as m(person) where m.person->>'id'=value->>'pickupMemberId'),'Unassigned') end,case when value ? 'excludedDates' then 'Skipped dates: '||(value->'excludedDates')::text end,case when value ? 'excludedRanges' then 'Holiday dates: '||(value->'excludedRanges')::text end,case when value ? 'done' then case when (value->>'done')::boolean then 'Done' else 'To do' end end) end;
        involved := coalesce(value->'memberIds',previous->'memberIds',jsonb_build_array(coalesce(value->>'memberId',previous->>'memberId',actor_member)));
        if coalesce(value,previous) ? 'pickupMemberId' then involved := involved||jsonb_build_array(coalesce(value,previous)->>'pickupMemberId'); end if;
        if coalesce(value,previous) ? 'dropOffMemberId' then involved := involved||jsonb_build_array(coalesce(value,previous)->>'dropOffMemberId'); end if;
        if before_text is distinct from after_text then history := history||jsonb_build_array(jsonb_build_object('id',gen_random_uuid()::text,'actorId',auth.uid()::text,'actorMemberId',actor_member,'actorName',coalesce(actor_name,'Family member'),'createdAt',to_jsonb(to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),'collection',collection,'recordId',case when collection='comments' then coalesce(value,previous)->>'eventId' else record_id end,'title',coalesce(value->>'title',previous->>'title','Event discussion'),'before',left(coalesce(before_text,''),500),'after',left(coalesce(after_text,''),500),'memberIds',involved,'source','server')); end if;
      end if;
      select coalesce(jsonb_agg(e order by ord),'[]'::jsonb) into items
        from jsonb_array_elements(document->collection) with ordinality as entry(e,ord)
        where e->>'id' <> record_id;
      if action = 'upsert' then
        -- A date and meal slot have one plan, even if two clients plan it concurrently.
        if collection = 'meals' then
          select coalesce(jsonb_agg(e),'[]'::jsonb) into items from jsonb_array_elements(items) e
            where not (e->>'date' = change->'value'->>'date' and e->>'slot' = change->'value'->>'slot');
        end if;
        items := items || jsonb_build_array(change->'value');
      end if;
      document := jsonb_set(document,array[collection],items);
      if action='remove' and collection='events' then
        document := case when document ? 'comments' then jsonb_set(document,'{comments}',(select coalesce(jsonb_agg(c),'[]') from jsonb_array_elements(document->'comments') c where c->>'eventId'<>record_id)) else document end;
        document := case when document ? 'eventLinks' then jsonb_set(document,'{eventLinks}',(select coalesce(jsonb_agg(c),'[]') from jsonb_array_elements(document->'eventLinks') c where c->>'eventId'<>record_id)) else document end;
      end if;
      if action='remove' and collection='routines' and document ? 'routineChecks' then document := jsonb_set(document,'{routineChecks}',(select coalesce(jsonb_agg(c),'[]') from jsonb_array_elements(document->'routineChecks') c where c->>'routineId'<>record_id)); end if;
      if action='remove' and collection='rewards' and document ? 'rewardClaims' then document := jsonb_set(document,'{rewardClaims}',(select coalesce(jsonb_agg(c),'[]') from jsonb_array_elements(document->'rewardClaims') c where c->>'rewardId'<>record_id)); end if;
      if collection='rewardClaims' and action='upsert' and previous is null and public.planner_reward_balance(document,value->>'memberId')<0 then raise exception 'Not enough stars for this reward.'; end if;
    else raise exception 'Unknown change.';
    end if;
  end loop;
  if jsonb_array_length(history)>0 then document := jsonb_set(document,'{activity}',(select coalesce(jsonb_agg(e order by ord),'[]') from jsonb_array_elements(coalesce(document->'activity','[]')||history) with ordinality x(e,ord) where ord>greatest(0,jsonb_array_length(coalesce(document->'activity','[]')||history)-200))); end if;
  if not public.planner_validate_data(document) then raise exception 'The updated family data is not valid.'; end if;
  update public.planner_households set data = document, updated_at = clock_timestamp() where id = family_id;
  return document;
end;
$$;

create or replace function public.planner_save_push(subscription jsonb, preferences jsonb)
returns void language plpgsql security definer set search_path = '' as $$
declare family uuid; endpoint_value text := subscription->>'endpoint';
begin
  select household_id into family from public.planner_memberships where user_id=auth.uid();
  if family is null then raise exception 'Join a family before enabling reminders.'; end if;
  perform 1 from public.planner_households where id=family for update;
  if not public.planner_is_member(family) then raise exception 'This family space is private.'; end if;
  -- Only browser push services may be contacted by the sender; no arbitrary URLs.
  if endpoint_value is null or length(endpoint_value)>2048 or
    endpoint_value !~ '^https://(fcm\.googleapis\.com|updates\.push\.services\.mozilla\.com|web\.push\.apple\.com|[a-z0-9-]+\.notify\.windows\.com)/[A-Za-z0-9_/?=&%+.:~-]+$'
    then raise exception 'This browser uses an unsupported push service.'; end if;
  if coalesce(subscription->'keys'->>'p256dh','') !~ '^[A-Za-z0-9_-]{80,100}={0,2}$' or
     coalesce(subscription->'keys'->>'auth','') !~ '^[A-Za-z0-9_-]{20,30}={0,2}$'
    then raise exception 'The notification subscription is invalid.'; end if;
  if not exists(select 1 from pg_timezone_names where name=preferences->>'timezone')
    then raise exception 'Choose a valid time zone.'; end if;
  insert into public.planner_push_subscriptions(household_id,user_id,endpoint,p256dh,auth,timezone,scope,event_minutes,chore_time,events_enabled,chores_enabled,snoozed_until)
  values(family,auth.uid(),endpoint_value,subscription->'keys'->>'p256dh',subscription->'keys'->>'auth',
    preferences->>'timezone',preferences->>'scope',(preferences->>'event_minutes')::integer,preferences->>'chore_time',
    (preferences->>'events_enabled')::boolean,(preferences->>'chores_enabled')::boolean,(preferences->>'snoozed_until')::timestamptz)
  on conflict(endpoint) do update set household_id=excluded.household_id,user_id=excluded.user_id,
    p256dh=excluded.p256dh,auth=excluded.auth,timezone=excluded.timezone,scope=excluded.scope,event_minutes=excluded.event_minutes,
    chore_time=excluded.chore_time,events_enabled=excluded.events_enabled,chores_enabled=excluded.chores_enabled,snoozed_until=excluded.snoozed_until;
end;
$$;

revoke all on function public.planner_validate_data(jsonb) from public, anon, authenticated;

revoke all on function public.planner_reward_balance(jsonb,text), public.planner_validate_features(jsonb) from public, anon, authenticated;

revoke all on function public.planner_apply_changes(uuid,jsonb) from public, anon;

grant execute on function public.planner_apply_changes(uuid,jsonb) to authenticated;

notify pgrst, 'reload schema';

commit;

